const previousBusinessExtra=renderExtraView;renderExtraView=function(v){if(v==='businessSettings')return state.role==='Owner HQ'?businessSettings():head('Owner access required.','');if(v==='pPortfolio')return portfolioEditor();return previousBusinessExtra(v);};
function demoOpeningLabel(id){return id==='alex'?'Demo opening · Tomorrow at 10:00 AM':id==='jordan'?'Demo opening · Today at 3:15 PM':'Watkins · Demo availability';}
const baseBarberCard=barberCard;barberCard=function(b){return baseBarberCard(b).replace('</button>',`<span class="demo-opening">${demoOpeningLabel(b.id)}</span></button>`);};
function isDemoSlot(t){return (state.barber==='alex'&&state.date===days[0]&&t==='10:00 AM')||(state.barber==='jordan'&&state.date===today&&t==='3:15 PM');}
const baseBusy=sampleBusy;sampleBusy=function(t,len){const blocked=extras.blocks.some(b=>b.barber===state.barber&&b.date===state.date&&minutes(t)<clockMinutes(b.end)&&minutes(t)+len>clockMinutes(b.start));if(blocked)return true;return isDemoSlot(t)?false:state.barber==='watkins'?false:baseBusy(t,len);};
const baseBooking=booking;booking=function(){let html=baseBooking();if(state.step===1){const tiles=`<div class="personal-services booking-service-grid">${servicesFor(state.barber).filter(s=>s.active!==false).map(s=>`<button type="button" class="choice service-card ${(state.services||[]).includes(s.id)?'selected':''}" data-service="${s.id}" role="checkbox" aria-checked="${(state.services||[]).includes(s.id)}">${serviceIcon(s)}<h3>${esc(s.name)}</h3><span class="muted">${s.min} min</span><strong class="service-price">${money(s.price)}</strong></button>`).join('')}</div>`;html=html.replace(/<div class="booking-choices">[\s\S]*?<\/div><div class="booking-footer">/,tiles+'<div class="booking-footer">');}if(state.step===2&&!days.includes(today)){const d=`<button class="date ${state.date===today?'selected':''}" data-date="${today}"><span>Today</span><strong>${dateObj(today).getDate()}</strong><span>${pretty(today,{month:'short'})}</span></button>`;html=html.replace('aria-label="Appointment date">','aria-label="Appointment date">'+d);}return html;};
const baseConfirm=confirmBooking;confirmBooking=function(){const existing=bookings.find(x=>x.id===state.editing);if(existing&&!HFAppRules.accessible(existing,state.role,activeBarberId()))return;const policy=existing?.policy||structuredClone(extras.bookingPolicy);baseConfirm();const b=bookings.find(x=>x.id===state.latest);if(b&&state.view==='success'){b.policy=policy;b.depositDueCents=HFAppRules.depositCents(b.estimateCents,policy);if(policy.enabled){b.paymentState='pending';b.status='pending_payment';}save();render();}};
const baseSuccess=success;success=function(){const b=bookings.find(x=>x.id===state.latest);if(b?.status!=='pending_payment')return baseSuccess();return `<section class="success">${head('Finish your booking.','Prepayment is required before this appointment can be confirmed.')}<section class="panel"><h2>${cents(b.depositDueCents)} due</h2><p>${pretty(b.date)} · ${b.time} · ${esc(barbers.find(x=>x.id===b.barber)?.name)}</p><p class="muted">Payment setup is pending. This demo appointment is not confirmed and no money has been collected.</p>${paymentMethodsDisplay()}<button class="btn full" disabled>Payment connection required</button></section>${linkPage('My visits','bookings','Customer')}</section>`;};
function businessError(form,err){const target=form.querySelector('.business-error')||form.querySelector('#booking-error');if(target)target.textContent=err.message;else toast(err.message);}
function registerService(value){const found=services.findIndex(s=>s.id===value.id);if(found<0)services.push({...value});}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el)return;const d=el.dataset;
 // Intercept legacy appointment controls so all roles use the same policy checks.
 if(['cancel','cancel-confirm','reschedule'].includes(d.action)){e.preventDefault();e.stopImmediatePropagation();const b=bookings.find(x=>x.id===d.id);if(b)appointmentDialog(b,d.action==='reschedule'?'reschedule':'cancel');return;}
 if(!d.business)return;e.preventDefault();e.stopImmediatePropagation();const id=catalogBarber();
 switch(d.business){case'new-service':if(isStaff()){state.editMenuService='new';render();}break;case'edit-service':if(isStaff()){state.editMenuService=d.id;render();}break;case'close-editor':state.editMenuService=null;render();break;
 case'toggle-service':{if(!isStaff())return;const menu=servicesFor(id),s=menu.find(x=>x.id===d.id);if(!s)return;if(s.active!==false&&menu.filter(x=>x.active!==false).length===1){toast('Keep at least one service enabled.');return;}s.active=s.active===false;save();render();break;}
 case'choose-service':{const s=servicesFor(state.barber).find(x=>x.id===d.id&&x.active!==false);if(!s)return;state.services=[s.id];state.service=s.id;state.time='';state.editing=null;state.step=2;go('book');break;}
 case'portfolio':if(isStaff())go('pPortfolio');break;case'business-settings':if(state.role==='Owner HQ')go('businessSettings');break;
 case'remove-work':if(isStaff()){extras.portfolios[id]=portfolioItems(id).filter(x=>x.id!==d.id);save();render();}break;
 case'approve-work':case'decline-work':{if(!isStaff())return;const r=extras.portfolioRequests.find(x=>x.id===d.id&&x.barber===id&&x.status==='pending');if(!r)return;if(d.business==='approve-work'){if(portfolioItems(id).length>=8){toast('Remove a photo before adding another.');return;}(extras.portfolios[id]||=[]).push({id:r.id,src:r.src,caption:r.caption,sourceVisit:r.visit});r.status='approved';}else r.status='declined';save();render();break;}
 case'remove-memory':{if(state.role!=='Customer')return;const b=bookings.find(x=>x.id===d.visit&&x.client==='John B.');if(!b)return;const m=extras.hairMemories[b.id];m.photos=m.photos.filter(x=>x.id!==d.id);save();render();break;}
 case'cancel':case'reschedule':{const b=bookings.find(x=>x.id===d.id);if(b)appointmentDialog(b,d.business);break;}
 }
},true);
